template <bool Purposed, class Result>
ReadingRequest<Purposed, Result>& ReadingRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    ReadingRequest<false> readingsMinimal() const {
        return ReadingRequest<false>(binding_.get(), true);
    }

    ReadingRequest<false> readings() const {
        return ReadingRequest<false>(binding_.get());
    }

    ReadingRequest<false> readingsWithChildren() const {
        return ReadingRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
